// Package calc evaluates signed 64-bit integer arithmetic expressions.
//
// Grammar (spaces and tabs may separate any two tokens):
//
//	expr    := term    (('+' | '-') term)*
//	term    := unary   (('*' | '/' | '%') unary)*
//	unary   := '-' unary | primary
//	primary := NUMBER | '(' expr ')'
//	NUMBER  := [0-9]+
//
// Parsing is iterative (operator precedence with explicit stacks), so deeply
// nested input cannot exhaust the call stack.
package calc

import (
	"errors"
	"math"
)

// Errors reported by Evaluate.
var (
	ErrSyntax      = errors.New("syntax error")
	ErrDivByZero   = errors.New("division by zero")
	ErrOverflow    = errors.New("integer overflow")
	errUnreachable = errors.New("internal: malformed operator stack")
)

type op byte

const (
	opAdd   op = '+'
	opSub   op = '-'
	opMul   op = '*'
	opDiv   op = '/'
	opRem   op = '%'
	opNeg   op = 'n'
	opParen op = '('
)

func (o op) precedence() int {
	switch o {
	case opAdd, opSub:
		return 1
	case opMul, opDiv, opRem:
		return 2
	case opNeg:
		return 3
	}
	return 0
}

// IsBlank reports whether line consists solely of spaces and tabs.
func IsBlank(line []byte) bool {
	for _, c := range line {
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return true
}

// Evaluate parses and evaluates a single expression. It returns ErrSyntax,
// ErrDivByZero or ErrOverflow on failure.
func Evaluate(src []byte) (int64, error) {
	var m machine
	expectOperand := true

	for i := 0; i < len(src); {
		c := src[i]
		switch {
		case c == ' ' || c == '\t':
			i++
			continue
		case isDigit(c):
			if !expectOperand {
				return 0, ErrSyntax
			}
			start := i
			for i < len(src) && isDigit(src[i]) {
				i++
			}
			v, err := parseNumber(src[start:i])
			if err != nil {
				return 0, err
			}
			m.values = append(m.values, v)
			expectOperand = false
			continue
		}

		i++
		if expectOperand {
			switch c {
			case '-':
				m.ops = append(m.ops, opNeg)
			case '(':
				m.ops = append(m.ops, opParen)
			default:
				return 0, ErrSyntax
			}
			continue
		}

		switch o := op(c); o {
		case opAdd, opSub, opMul, opDiv, opRem:
			if err := m.pushBinary(o); err != nil {
				return 0, err
			}
			expectOperand = true
		case ')':
			if err := m.closeParen(); err != nil {
				return 0, err
			}
		default:
			return 0, ErrSyntax
		}
	}

	if expectOperand {
		return 0, ErrSyntax
	}
	return m.finish()
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// parseNumber converts a run of ASCII digits to int64, rejecting values
// above math.MaxInt64.
func parseNumber(digits []byte) (int64, error) {
	var v int64
	for _, d := range digits {
		n := int64(d - '0')
		if v > (math.MaxInt64-n)/10 {
			return 0, ErrOverflow
		}
		v = v*10 + n
	}
	return v, nil
}

// machine holds the operand and operator stacks of the shunting-yard parser.
type machine struct {
	values []int64
	ops    []op
}

// pushBinary reduces pending operators that bind at least as tightly as o
// (giving left associativity), then pushes o.
func (m *machine) pushBinary(o op) error {
	prec := o.precedence()
	for len(m.ops) > 0 {
		top := m.ops[len(m.ops)-1]
		if top == opParen || top.precedence() < prec {
			break
		}
		if err := m.reduce(); err != nil {
			return err
		}
	}
	m.ops = append(m.ops, o)
	return nil
}

// closeParen reduces up to and including the matching '('.
func (m *machine) closeParen() error {
	for len(m.ops) > 0 {
		if m.ops[len(m.ops)-1] == opParen {
			m.ops = m.ops[:len(m.ops)-1]
			return nil
		}
		if err := m.reduce(); err != nil {
			return err
		}
	}
	return ErrSyntax
}

func (m *machine) finish() (int64, error) {
	for len(m.ops) > 0 {
		if m.ops[len(m.ops)-1] == opParen {
			return 0, ErrSyntax
		}
		if err := m.reduce(); err != nil {
			return 0, err
		}
	}
	if len(m.values) != 1 {
		return 0, ErrSyntax
	}
	return m.values[0], nil
}

// reduce pops the top operator and applies it to the top operand(s).
func (m *machine) reduce() error {
	o := m.ops[len(m.ops)-1]
	m.ops = m.ops[:len(m.ops)-1]

	if o == opNeg {
		n := len(m.values)
		if n < 1 {
			return errUnreachable
		}
		v, err := neg(m.values[n-1])
		if err != nil {
			return err
		}
		m.values[n-1] = v
		return nil
	}

	n := len(m.values)
	if n < 2 {
		return errUnreachable
	}
	v, err := apply(o, m.values[n-2], m.values[n-1])
	if err != nil {
		return err
	}
	m.values[n-2] = v
	m.values = m.values[:n-1]
	return nil
}

func apply(o op, a, b int64) (int64, error) {
	switch o {
	case opAdd:
		return add(a, b)
	case opSub:
		return sub(a, b)
	case opMul:
		return mul(a, b)
	case opDiv:
		return div(a, b)
	case opRem:
		return rem(a, b)
	}
	return 0, errUnreachable
}

func neg(a int64) (int64, error) {
	if a == math.MinInt64 {
		return 0, ErrOverflow
	}
	return -a, nil
}

func add(a, b int64) (int64, error) {
	s := a + b
	// Overflow iff both operands share a sign that differs from the sum's.
	if (a^s)&(b^s) < 0 {
		return 0, ErrOverflow
	}
	return s, nil
}

func sub(a, b int64) (int64, error) {
	d := a - b
	// Overflow iff the operands differ in sign and the result's sign differs from a's.
	if (a^b)&(a^d) < 0 {
		return 0, ErrOverflow
	}
	return d, nil
}

func mul(a, b int64) (int64, error) {
	if a == 0 || b == 0 {
		return 0, nil
	}
	p := a * b
	if (a == -1 && b == math.MinInt64) || (b == -1 && a == math.MinInt64) || p/b != a {
		return 0, ErrOverflow
	}
	return p, nil
}

func div(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	if a == math.MinInt64 && b == -1 {
		return 0, ErrOverflow
	}
	return a / b, nil // Go division truncates toward zero.
}

func rem(a, b int64) (int64, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	if b == -1 {
		return 0, nil // Avoids MinInt64 % -1 trapping on some architectures.
	}
	return a % b, nil // Sign follows the dividend.
}

package calc

import (
	"errors"
	"strings"
	"testing"
)

func TestEvaluate(t *testing.T) {
	tests := []struct {
		in   string
		want int64
		err  error
	}{
		{"1 + 2 * 3", 7, nil},
		{"-7 / 2", -3, nil},
		{"-7 % 3", -1, nil},
		{"7 % -3", 1, nil},
		{"10 - 4 - 3", 3, nil},
		{"--5", 5, nil},
		{"-(2 + 3)", -5, nil},
		{"\t( 1 )\t", 1, nil},
		{"(-9223372036854775807 - 1) % -1", 0, nil},
		{"-9223372036854775807 - 1", -9223372036854775808, nil},
		{"9223372036854775807", 9223372036854775807, nil},
		{"(1 + 2", 0, ErrSyntax},
		{"1 +", 0, ErrSyntax},
		{"()", 0, ErrSyntax},
		{"1 2", 0, ErrSyntax},
		{"+1", 0, ErrSyntax},
		{"1)", 0, ErrSyntax},
		{"abc", 0, ErrSyntax},
		{"1\r", 0, ErrSyntax},
		{"1 / 0", 0, ErrDivByZero},
		{"5 % 0", 0, ErrDivByZero},
		{"9223372036854775807 + 1", 0, ErrOverflow},
		{"9223372036854775808", 0, ErrOverflow},
		{"-9223372036854775808", 0, ErrOverflow},
		{"(-9223372036854775807 - 1) / -1", 0, ErrOverflow},
		{"(-9223372036854775807 - 1) * -1", 0, ErrOverflow},
		{"-(-9223372036854775807 - 1)", 0, ErrOverflow},
		{"3037000500 * 3037000500", 0, ErrOverflow},
		{"3037000499 * 3037000499", 9223372030926249001, nil},
	}
	for _, tt := range tests {
		got, err := Evaluate([]byte(tt.in))
		if !errors.Is(err, tt.err) || (err == nil && got != tt.want) {
			t.Errorf("Evaluate(%q) = %d, %v; want %d, %v", tt.in, got, err, tt.want, tt.err)
		}
	}
}

func TestDeepNesting(t *testing.T) {
	const depth = 1_000_000
	src := strings.Repeat("(", depth) + "42" + strings.Repeat(")", depth)
	if got, err := Evaluate([]byte(src)); err != nil || got != 42 {
		t.Fatalf("got %d, %v", got, err)
	}
	src = strings.Repeat("-", depth+1) + "1"
	if got, err := Evaluate([]byte(src)); err != nil || got != -1 {
		t.Fatalf("got %d, %v; want -1", got, err)
	}
}

func TestParseNumber(t *testing.T) {
	tests := []struct {
		in   string
		want int64
		err  error
	}{
		{"0", 0, nil},
		{"00009223372036854775807", 9223372036854775807, nil},
		{"9223372036854775806", 9223372036854775806, nil},
		{"9223372036854775808", 0, ErrOverflow},
		{"99999999999999999999", 0, ErrOverflow},
	}
	for _, tt := range tests {
		got, err := parseNumber([]byte(tt.in))
		if !errors.Is(err, tt.err) || got != tt.want {
			t.Errorf("parseNumber(%q) = %d, %v; want %d, %v", tt.in, got, err, tt.want, tt.err)
		}
	}
}

// Command app evaluates one signed 64-bit integer expression per line of
// standard input, printing each result or "error".
package main

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"

	"calc/calc"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	in := bufio.NewReaderSize(r, 64*1024)
	out := bufio.NewWriterSize(w, 64*1024)
	var buf []byte

	for {
		line, err := in.ReadSlice('\n')
		if errors.Is(err, bufio.ErrBufferFull) {
			// Accumulate an over-long line before evaluating it.
			buf = append(buf[:0], line...)
			for errors.Is(err, bufio.ErrBufferFull) {
				line, err = in.ReadSlice('\n')
				buf = append(buf, line...)
			}
			line = buf
		}
		if err != nil && !errors.Is(err, io.EOF) {
			return err
		}
		if n := len(line); n > 0 && line[n-1] == '\n' {
			line = line[:n-1]
		}
		if !calc.IsBlank(line) {
			if v, evalErr := calc.Evaluate(line); evalErr != nil {
				out.WriteString("error\n")
			} else {
				out.Write(strconv.AppendInt(nil, v, 10))
				out.WriteByte('\n')
			}
		}
		if err != nil { // io.EOF
			break
		}
	}
	return out.Flush()
}
